import { useCallback, useEffect } from 'react';

import { useHoneycombTooltipPinnedState } from '../store/selectors.js';
import { useSetStateTooltip } from '../store/store.js';

export const useTooltipEventListeners = (tooltipRef: HTMLDivElement | null) => {
  const setTooltipState = useSetStateTooltip();

  const pinned = useHoneycombTooltipPinnedState();

  const unpinTooltip = useCallback(() => {
    if (pinned) {
      setTooltipState({ pinned: false });
    }
  }, [pinned]);

  const onEscapeKeyPressedHandler = useCallback(
    (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        unpinTooltip();
      }
    },
    [unpinTooltip],
  );

  const onClickOutsideOverlayHandler = useCallback(
    (event: MouseEvent) => {
      if (!tooltipRef?.contains(event.target as Node)) {
        unpinTooltip();
      }
    },
    [tooltipRef, unpinTooltip],
  );

  useEffect(() => {
    window.addEventListener('click', onClickOutsideOverlayHandler);
    window.addEventListener('keyup', onEscapeKeyPressedHandler);

    return () => {
      window.removeEventListener('click', onClickOutsideOverlayHandler);
      window.removeEventListener('keyup', onEscapeKeyPressedHandler);
    };
  }, [onClickOutsideOverlayHandler, onEscapeKeyPressedHandler]);
};
